solution:
def count_convoys(target: int, position: list[int], speed: list[int]) -> int:
    stack = []                                   # one arrival time per convoy, decreasing
    for p, s in sorted(zip(position, speed)):    # from the back of the road to the front
        t = (target - p) / s                     # when this car would arrive alone
        while stack and stack[-1] <= t:
            stack.pop()                          # that convoy catches this car: they merge
        stack.append(t)
    return len(stack)

perf.naive:
def count_convoys(target: int, position: list[int], speed: list[int]) -> int:
    times = [(target - p) / s for p, s in zip(position, speed)]
    convoys = 0
    for i in range(len(times)):
        # car i leads a convoy unless some car ahead of it arrives no earlier
        if not any(position[j] > position[i] and times[j] >= times[i] for j in range(len(times))):
            convoys += 1
    return convoys
